function commit(points,bridgeApproved=false){const alreadyEmergency=city.emergency.active;if(['ufo','whirlpool','toxicCloud','spaceJunk'].includes(tool)){const hazard=tool,toxic=tool==='toxicCloud',p=points.at(-1),r=tool==='ufo'?startUfo(city,p.x,p.y):tool==='whirlpool'?startWhirlpool(city,p.x,p.y):toxic?startToxicCloud(city,p.x,p.y):startSpaceJunk(city,p.x,p.y);if(!r.ok){notify(r.error);return r;}undo=[];if(!alreadyEmergency)city.emergency.resumeSpeed=speed;emergencyHeld=false;emergencyElapsed=0;goToFire(tool);setTool('dispatchFire');recompute(city);update();persist(AUTO,true);notify(hazard==='ufo'?'Alien craft approaching. Sound the early warning siren.':hazard==='whirlpool'?'Whirlpool reported. Shoreline connections are at risk.':toxic?'Toxic cloud reported. Occupants will leave affected zones.':'Space junk is falling. Prepare firefighters near the impact zone.');emergencyPanel();return r;}if(['riot','dispatchPolice'].includes(tool)){const p=points.at(-1),start=tool==='riot',r=start?startRiot(city,p.x,p.y):dispatchPolice(city,p.x,p.y);if(!r.ok){notify(r.error);return r;}undo=[];if(start){if(!alreadyEmergency)city.emergency.resumeSpeed=speed;emergencyHeld=false;emergencyElapsed=0;goToFire('riot');setTool('dispatchPolice');}recompute(city);update();persist(AUTO,true);notify(start?'Riot reported. Dispatch police near the crowd.':'Police dispatched.');if(start)emergencyPanel();return r;}if(['locust','dispatchCropDuster'].includes(tool)){const p=points.at(-1),start=tool==='locust',r=start?startLocusts(city,p.x,p.y):dispatchCropDuster(city,p.x,p.y);if(!r.ok){notify(r.error);return r;}undo=[];if(start){if(!alreadyEmergency)city.emergency.resumeSpeed=speed;emergencyHeld=false;emergencyElapsed=0;goToFire('locust');setTool('dispatchCropDuster');}recompute(city);update();persist(AUTO,true);notify(start?'Locust swarm reported. Dispatch crop dusters ahead of its path.':'Crop duster dispatched. Spray arrives in two response steps.');if(start)emergencyPanel();return r;}if(['tornado','earthquake','ignite','dispatchFire'].includes(tool)){const p=points.at(-1),storm=tool==='tornado',quake=tool==='earthquake',start=tool!=='dispatchFire',result=storm?startTornado(city,p.x,p.y):quake?startEarthquake(city,p.x,p.y):start?ignite(city,p.x,p.y):dispatchFire(city,p.x,p.y);if(result.ok){undo=[];if(start){if(!alreadyEmergency)city.emergency.resumeSpeed=speed;emergencyHeld=false;emergencyElapsed=0;goToFire(storm?'tornado':quake?'earthquake':fireLocationAt(city,p.x,p.y));setTool('dispatchFire');}recompute(city);update();persist(AUTO,true);notify(storm?'Tornado reported. Restore damaged routes and fight resulting fires.':quake?'Earthquake underway. Inspect broken networks and fight any resulting fires.':start?'Fire reported. Dispatch firefighters near the flames.':'Firefighters dispatched.');if(storm)emergencyPanel();}else notify(result.error);return result;}if(['road','rail','highway'].includes(tool)&&!bridgeApproved){const plan=planBuild(city,tool,points,density);if(plan.ok&&(plan.tunnel||plan.points.some(p=>city.tiles[idx(p.x,p.y)].terrain==='water'))){const savedPoints=points.map(p=>({...p}));dialog(plan.tunnel?'City engineers · tunnel proposal':'City engineers · bridge proposal',`<p>${plan.tunnel?`Bore ${plan.points.length-2} underground tiles between level portals. Terrain and buildings above remain intact. `:''}${tool==='highway'?'A highway':tool==='rail'?'A rail':'A road'} crossing with ${plan.tunnel?plan.points.length:plan.points.filter(p=>city.tiles[idx(p.x,p.y)].terrain==='water').length} ${plan.tunnel?'route':'new water'} tiles. Total construction cost: <strong>${money(plan.cost)}</strong>.</p><div class="actions"><button id="acceptBridge" class="primary">${plan.tunnel?'Build tunnel':'Build crossing'}</button><button id="cancelBridge">Cancel</button></div>`);$('#acceptBridge').onclick=()=>{closeDialog();commit(savedPoints,true);};$('#cancelBridge').onclick=closeDialog;return{ok:false,pending:true};}}const before=serializeCity(city);const result=build(city,tool,points,density);gameAudio.play(result.ok?(tool==='bulldoze'?'bulldoze':'build'):'error');if(result.ok){if(!speed&&!city.emergency.active){undo.push(before);if(undo.length>20)undo.shift();}notify(`${LABEL[tool]} ${LANDSCAPE[tool]?'applied':tool==='bulldoze'?'cleared':'built'} · ${money(result.cost)}`);persist(AUTO,true);update();}else notify(result.error);return result;}
function undoBuild(){if(city.emergency.active)return notify('Construction undo is unavailable during a disaster.');if(speed)return notify('Pause the simulation before undoing construction.');if(!undo.length)return notify('No construction to undo. History resets when time advances.');city=validateSave(JSON.parse(undo.pop()));update();persist(AUTO,true);notify('Last construction undone.');}
function dialog(title,html){if(!city.emergency.active)setSpeed(0);$('#dialogTitle').textContent=title;$('#dialogBody').innerHTML=html;if(!$('#dialog').open)$('#dialog').showModal();}
