const localPoint=e=>{const b=canvas.getBoundingClientRect();return{x:e.clientX-b.left,y:e.clientY-b.top};};
canvas.addEventListener('contextmenu',e=>e.preventDefault());
canvas.addEventListener('pointerdown',e=>{if(pointer)return;canvas.focus({preventScroll:true});canvas.setPointerCapture(e.pointerId);const p=localPoint(e);const pan=monthlyUpdate||e.button===2||e.button===1||space||tool==='pan';pointer={id:e.pointerId,x:p.x,y:p.y,pan,moved:false,origin:renderer.pick(p.x,p.y)};if(!pan&&pointer.origin){renderer.drag=pointer.origin;renderer.hover=pointer.origin;}renderer.dirty=true;});
canvas.addEventListener('pointermove',e=>{const p=localPoint(e);if(pointer&&e.pointerId===pointer.id){const dx=p.x-pointer.x,dy=p.y-pointer.y;if(Math.abs(dx)+Math.abs(dy)>2)pointer.moved=true;if(pointer.pan){renderer.pan.x+=dx;renderer.pan.y+=dy;pointer.x=p.x;pointer.y=p.y;}else renderer.hover=renderer.pick(p.x,p.y);}else renderer.hover=renderer.pick(p.x,p.y);renderer.dirty=true;if(renderer.hover)$('#coordinates').textContent=`TILE ${renderer.hover.x+1}, ${renderer.hover.y+1} · ${LABEL[tool]}`;});
canvas.addEventListener('pointerup',e=>{if(!pointer||e.pointerId!==pointer.id)return;const p=localPoint(e),end=renderer.pick(p.x,p.y),start=pointer.origin;if(!pointer.pan&&start&&end){if(e.shiftKey)notify('Construction cancelled.');else if(tool==='query')showQuery(end);else commit(selection(tool,start,end));}space=space&&pointer.pan;pointer=null;renderer.drag=null;renderer.dirty=true;});
canvas.addEventListener('pointercancel',()=>{pointer=null;renderer.drag=null;renderer.dirty=true;});canvas.addEventListener('pointerleave',()=>{if(!pointer){renderer.hover=null;renderer.dirty=true;}});
canvas.addEventListener('wheel',e=>{e.preventDefault();renderer.setZoom(renderer.zoom*(e.deltaY<0?1.1:1/1.1));update();},{passive:false});
window.addEventListener('keydown',e=>{if($('#dialog').open||['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName))return;if(e.code==='Space'){if(nativeSpaceTarget(e.target))return;e.preventDefault();space=true;return;}if(e.key==='Escape'){pointer=null;renderer.drag=null;renderer.dirty=true;return;}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();undoBuild();return;}if(e.ctrlKey||e.metaKey||e.altKey)return;const map={r:'road',p:'park',b:'bulldoze',m:'pan','1':'residential','2':'commercial','3':'industrial',e:'coal',l:'powerline',w:'pump',u:'pipe',x:'removePipe',g:'landfill',d:'dezone',q:'query'};if(map[e.key.toLowerCase()])setTool(map[e.key.toLowerCase()]);if(e.key==='?')showHelp();if(e.key==='Home'){renderer.center();update();}if(['+','='].includes(e.key))$('#zoomIn').click();if(e.key==='-')$('#zoomOut').click();if(e.target===canvas&&e.key.startsWith('Arrow')){e.preventDefault();const p=renderer.hover||{x:24,y:24},d={ArrowUp:[0,-1],ArrowDown:[0,1],ArrowLeft:[-1,0],ArrowRight:[1,0]}[e.key];if(inside(p.x+d[0],p.y+d[1]))renderer.hover={x:p.x+d[0],y:p.y+d[1]};renderer.dirty=true;}if(e.target===canvas&&e.key==='Enter'&&renderer.hover){e.preventDefault();if(tool==='query')showQuery(renderer.hover);else if(tool!=='pan')commit([renderer.hover]);}});
window.addEventListener('keyup',e=>{if(e.code==='Space'){const wasPanning=pointer?.pan||spacePanned;space=false;if(!wasPanning&&!$('#dialog').open&&!nativeSpaceTarget(e.target))setSpeed(speed?0:resumeScenarioSpeed(city));spacePanned=false;}});let spacePanned=false;canvas.addEventListener('pointermove',()=>{if(space&&pointer?.pan)spacePanned=true;});window.addEventListener('blur',()=>{space=false;pointer=null;renderer.drag=null;});
setInterval(async()=>{const now=performance.now();const dt=Math.min(now-lastTime,1000);lastTime=now;if(monthlyUpdate)return;if(!$('#dialog').open&&showPendingScenarioPopup({city:()=>city,dialog,element:$('#dialog'),close:closeDialog,status:scenarioPanel,save:()=>persist(AUTO,true)}))return;if(city.emergency.active){if(document.hidden||$('#dialog').open||emergencyHeld)return;emergencyElapsed+=dt;if(emergencyElapsed>=700){emergencyElapsed-=700;const r=stepFire(city);recompute(city);if(r.ended){speed=allowedSpeed(city,city.emergency.resumeSpeed)?city.emergency.resumeSpeed:resumeScenarioSpeed(city);notify('Emergency ended. Clear rubble and reconnect damaged services.');persist(AUTO,true);}else if(city.emergency.ufo)$('#news').textContent=city.emergency.ufo.warningSteps?'Alien craft approaching. Open Emergency and sound the warning siren.':'Alien attack: six beam strikes threaten surface structures. Rebuild after the craft departs.';else if(city.emergency.whirlpool)$('#news').textContent='Whirlpool: bridges and shoreline structures are being damaged. Restore connections after the water settles.';else if(city.emergency.toxicCloud)$('#news').textContent='Toxic cloud: occupants are leaving affected zones. Restore services and let the city redevelop after it disperses.';else if(city.emergency.spaceJunk)$('#news').textContent='Space junk is falling. Firefighters can contain impact fires but cannot stop falling debris.';else if(city.emergency.riot)$('#news').textContent='Riot underway. Dispatch police to disperse the crowd, and firefighters to contain fires.';else if(city.emergency.locust)$('#news').textContent='Locusts are feeding on vegetation. Dispatch crop dusters ahead of the swarm.';else if(city.emergency.tornado)$('#news').textContent=city.emergency.tornado.warningSteps?'Tornado approaching. Open Emergency to sound the early warning siren.':'Tornado moving through the city. Restore damaged services after it passes.';else if(city.emergency.earthquake)$('#news').textContent='Earthquake: damage is spreading from the epicenter. Firefighters cannot stop the shaking.';else if(r.destroyed)$('#news').textContent='Buildings were destroyed. Contain remaining fires, then restore services.';update();}return;}if(city.finance.pendingBudgetReview){if(!$('#dialog').open)showBudget();return;}if(!speed||document.hidden||$('#dialog').open||pointer)return;elapsed+=dt*speed;if(elapsed>=1800){elapsed-=1800;const source=city;let result;monthlyUpdate=true;$('#timeState').textContent='Calculating next month…';$('#city').setAttribute('aria-busy','true');try{const completed=await simulationRunner.advance(source);if(city!==source)return;if(completed.background)Object.assign(city,completed.city);result=completed.result;}catch(error){speed=0;notify('The next month could not be calculated: '+error.message);return;}finally{monthlyUpdate=false;$('#city').removeAttribute('aria-busy');update();}const presentation=scenarioEventPresentation(result.scenarioEvents);if(presentation.camera&&!city.emergency.active)scenarioCamera(presentation.camera);deliverScenarioSound(presentation.sound,gameAudio,city.emergency.active);const unlockedTechnology=newlyAvailable(city);if(unlockedTechnology.length){renderTools();notify('Now available: '+unlockedTechnology.map(k=>TECHNOLOGY[k].name).join(', '));}if(city.emergency.active){city.emergency.resumeSpeed=speed;emergencyElapsed=0;automaticDisasterFocus(playPreferences,()=>goToFire());if(city.emergency.ufo||city.emergency.whirlpool||city.emergency.toxicCloud){emergencyPanel();}else if(city.emergency.spaceJunk){setTool('dispatchFire');emergencyPanel();}else if(city.emergency.riot){setTool('dispatchPolice');emergencyPanel();}else if(city.emergency.locust){setTool('dispatchCropDuster');emergencyPanel();}else if(city.emergency.tornado?.warningSteps)emergencyPanel();notify(city.emergency.ufo?'Alien craft reported. Sound the early warning siren.':city.emergency.whirlpool?'Whirlpool reported. Open Emergency for recovery guidance.':city.emergency.toxicCloud?'Toxic cloud reported. Open Emergency for recovery guidance.':city.emergency.spaceJunk?'Space junk reported. Prepare firefighters for impact fires.':city.emergency.riot?'Riot reported. Dispatch police near the crowd.':city.emergency.locust?'Locust plague reported. Dispatch crop dusters to protect vegetation.':city.emergency.tornado?'Tornado reported. Open Emergency for recovery tools.':city.emergency.earthquake?'Earthquake reported. Open Emergency for recovery tools.':'Fire reported. Open Emergency to dispatch firefighters.');}if(result.scenarioEvent?.type==='announcement')$('#news').textContent=result.scenarioEvent.message;else if(city.emergency.tornado)$('#news').textContent='Tornado underway. The calendar waits until the emergency ends.';else if(city.emergency.earthquake)$('#news').textContent='Earthquake underway. The calendar is held while damage spreads.';else if(result.powerFailures.some(p=>p.contaminated))$('#news').textContent='Nuclear meltdown: radiation has contaminated the marked area. Contain fires and rebuild elsewhere.';else if(result.powerFailures.length)$('#news').textContent=`${result.powerFailures.length} overloaded power plants were destroyed. Dispatch firefighters and replace lost capacity.`;else if(city.stats.overloadedPlants)$('#news').textContent=`${city.stats.overloadedPlants} power plants are overloaded. Add capacity to their grids before six consecutive months pass.`;else if(result.scenarioEvent?.type==='addGoal')$('#news').textContent='Scenario goal added. Open Scenarios & status to read your updated objectives.';else if(result.scenarioEvent?.type==='camera')$('#news').textContent='Scenario view: '+(result.scenarioEvent.x+1)+', '+(result.scenarioEvent.y+1)+' at '+Math.round(result.scenarioEvent.zoom*100)+'% zoom. Pan freely or revisit it in Scenario status.';else if(result.scenarioEvent?.type==='sound')$('#news').textContent='Scenario sound cue: '+SCENARIO_SOUNDS[result.scenarioEvent.sound].name+'. See Scenario status for event history.';else if(result.businessOffered)$('#news').textContent='Business proposal: a private operator offers monthly income. Review Business deals in Budget or City desk.';else if(result.rewardsUnlocked.length)$('#news').textContent=`Reward offered: ${result.rewardsUnlocked.map(k=>REWARDS[k].name).join(', ')}. Open City desk → Rewards to place it when ready.`;else if(result.failedDeals)$('#news').textContent=`${result.failedDeals} neighbor deals failed. Penalties: ${money(result.regionalPenalty)}. Check connections and capacity.`;else if(result.loanPayment)$('#news').textContent=`Annual loan payments: ${money(result.loanPayment)}. Review the remaining schedule in Budget.`;else if(city.stats.transitStrike)$('#news').textContent='Transit workers are on strike. Restore the transit budget and run one month.';else if(city.stats.strikes.length)$('#news').textContent=civicAdvice(city);else if(result.left)$('#news').textContent=`${result.left} buildings lost occupants. Check power, water, garbage, road access, and demand.`;else if(result.industryChanges.farms||result.industryChanges.clean)$('#news').textContent=`Industry changed: ${result.industryChanges.farms} farms opened; ${result.industryChanges.clean} factories converted to clean technology.`;else if(result.grew)$('#news').textContent=`${result.grew} new buildings opened this month. ${city.stats.population} residents now call ${city.name} home.`;else $('#news').textContent=city.stats.balance<0?'Monthly spending exceeds revenue. Grow your tax base before adding more upkeep.':'The city is ticking along. Keep room for homes, shops, and jobs.';if(result.scenarioEvent?.type==='announcement')scenarioAnnouncement={city,message:result.scenarioEvent.message,until:now+10000};if(scenarioAnnouncement?.city===city&&now<scenarioAnnouncement.until&&!city.emergency.active)$('#news').textContent=scenarioAnnouncement.message;if(result.scenarioEnded){speed=0;persist(AUTO,true);scenarioPanel();}else if(result.scenarioEvents.length||city.month%3===0||result.rewardsUnlocked.length||result.businessOffered)persist(AUTO,true);update();}},200);
window.addEventListener('pagehide',()=>persist(AUTO,true));window.addEventListener('spritesready',()=>update());window.addEventListener('spriteserror',()=>notify('Building artwork could not load. Reload to try again.'));
